   "candidate_id": "chunk_tipo02_cp_art_121-b_01",
   "source_type": "tipo_02_codigo_penal",
   "title": "Artículo 121-B.- Lesiones graves por violencia contra las mujeres e integrantes del grupo familiar",
   "article_id": "121-B",
   "relation_types": [
